SELECT analytics_budget_facts.quarter, SUM(analytics_budget_facts.budget_variance) AS budget_variance FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2024 AND analytics_budget_facts.department = 'department_03' AND analytics_budget_facts.cost_center = 'cc_048' AND analytics_budget_facts.expense_category = 'expense_04' GROUP BY analytics_budget_facts.quarter ORDER BY analytics_budget_facts.quarter ASC LIMIT 12
